#!/bin/sh
# crates.sh - Writes crates.cue: the crates.io packages of a VectorChord Cargo.lock
#
# The darwin vchord build (enve.cue) compiles VectorChord offline from these, each a
# hashed fetch (Cargo.lock's checksum is the .crate's sha256). Rerun on a vchord bump:
#   helpers/vchord/crates.sh <VectorChord checkout>/Cargo.lock <version> > helpers/vchord/crates.cue
set -eu
lock="${1:?usage: crates.sh <Cargo.lock> <vchord version>}"
version="${2:?usage: crates.sh <Cargo.lock> <vchord version>}"
cat << HEADER
package vchord

// Generated by helpers/vchord/crates.sh from VectorChord $version's Cargo.lock: the
// crates.io packages its darwin build vendors, as \`fetch\` entries.
version: "$version"
crates: {
HEADER
awk '
  /^\[\[package\]\]/ { name = ""; ver = ""; registry = 0; sum = "" }
  /^name = / { name = $3; gsub(/"/, "", name) }
  /^version = / { ver = $3; gsub(/"/, "", ver) }
  /^source = "registry\+/ { registry = 1 }
  /^checksum = / {
    sum = $3; gsub(/"/, "", sum)
    if (registry) {
      key = "crate_" name "_" ver
      gsub(/[^A-Za-z0-9_]/, "_", key)
      printf "\t%s: {url: \"https://static.crates.io/crates/%s/%s-%s.crate\", sha256: \"%s\"}\n", key, name, name, ver, sum
    }
  }
' "$lock"
echo "}"
